// Javni MQTT nije autentificiran i izlaže ključ igrača. Ostaje isključen dok se ne uvede siguran relej.
const RELAY_ENABLED = false;

if (!game) return;
if (game.refresh) game.refresh();
const v = game.view(), rel = new Set();

try { openRoom(code, opts); } catch (e) {
