  if (x && !x.pid) { hostConns.delete(conn); try { conn.close(); } catch (e) {} }
}, 10000);

if (e && e.type === 'unavailable-id' && tries < 5) {
  if (!(opts && opts.recovery)) return openHostPeer(tries + 1, opts);
