window.addEventListener('beforeunload', (e) => {
  // Stanje partije je samo u memoriji domaćina; osvježavanje ga briše.
  if (game && (mode === 'host' || mode === 'hostp') && game.view().ph !== 'lobby' && game.view().ph !== 'final') {
    e.preventDefault();
    e.returnValue = '';
  }
});
